const menu=document.querySelector('.menu-toggle'),nav=document.getElementById('navigation');
menu.addEventListener('click',()=>{const open=menu.getAttribute('aria-expanded')!=='true';menu.setAttribute('aria-expanded',String(open));nav.classList.toggle('open',open);});
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&nav.classList.contains('open')){nav.classList.remove('open');menu.setAttribute('aria-expanded','false');menu.focus();}});
const looks={traditional:'Silk & celebration — Traditional glamour',soft:'Quietly radiant — Soft glow',occasion:'Grace in the details — Occasion artistry'},key='thanushiya-favourites-v1';let saved=new Set(),storageOK=true,filter='all';
try{const value=JSON.parse(localStorage.getItem(key)||'[]');if(Array.isArray(value))saved=new Set(value.filter(x=>Object.hasOwn(looks,x)));}catch{storageOK=false;}
const byId=id=>document.getElementById(id);
function render(){const names=[...saved].map(id=>looks[id]).join('; ');if(byId('enquiry-shortlist'))byId('enquiry-shortlist').textContent=names?'Your inspiration: '+names:'Have a favourite? Save it in the lookbook or tell us your vision below.';document.querySelectorAll('[data-look]').forEach(b=>{const selected=saved.has(b.dataset.look);b.setAttribute('aria-pressed',String(selected));b.textContent=selected?'Saved · remove':'Save this look';});if(!byId('look-status'))return;let count=0;document.querySelectorAll('[data-style]').forEach(c=>{c.hidden=!(filter==='all'||filter===c.dataset.style||(filter==='saved'&&saved.has(c.dataset.style)));if(!c.hidden)count++;});document.querySelectorAll('[data-filter]').forEach(b=>b.setAttribute('aria-pressed',String(filter===b.dataset.filter)));document.querySelectorAll('[data-look]').forEach(b=>{const selected=saved.has(b.dataset.look);b.setAttribute('aria-pressed',String(selected));b.textContent=selected?'Saved · remove':'Save this look';});byId('look-status').textContent=`${count} looks · ${saved.size} saved`;byId('empty-looks').hidden=count!==0;byId('shortlist-summary').textContent=names||'Save a look you love to include it in your enquiry.';byId('clear-looks').hidden=!saved.size;if(!storageOK)byId('storage-note').textContent='Browser storage is unavailable. Describe your preferred look in your enquiry.';}
function persist(){try{localStorage.setItem(key,JSON.stringify([...saved]));}catch{storageOK=false;}render();}
document.querySelectorAll('[data-look]').forEach(b=>b.addEventListener('click',()=>{saved.has(b.dataset.look)?saved.delete(b.dataset.look):saved.add(b.dataset.look);persist();}));document.querySelectorAll('[data-filter]').forEach(b=>b.addEventListener('click',()=>{filter=b.dataset.filter;render();}));byId('clear-looks')?.addEventListener('click',()=>{saved.clear();persist();});render();
const form=byId('enquiry-form');if(form){const date=form.querySelector('[name="date"]'),now=new Date();date.min=[now.getFullYear(),String(now.getMonth()+1).padStart(2,'0'),String(now.getDate()).padStart(2,'0')].join('-');form.addEventListener('submit',event=>{event.preventDefault();const d=new FormData(form),inspiration=[...saved].map(id=>looks[id]).join('; ')||'Please guide me.';const message=`Hello Magila / Thanushiya Bridal Studio!\nName: ${d.get('name')}\nDate: ${d.get('date')}\nOccasion: ${d.get('occasion')}\nLocation: ${d.get('location')}\nFavourite looks: ${inspiration}\nVision: ${d.get('vision')||'Please guide me.'}\nPlease share availability and a personalised quote.`;const url='https://api.whatsapp.com/send?phone=917418086824&text='+encodeURIComponent(message);window.open(url,'_blank','noopener,noreferrer');const note=byId('form-note');note.textContent='Your message is ready. Review and send it in WhatsApp. If it did not open, ';const a=document.createElement('a');a.href=url;a.target='_blank';a.rel='noopener noreferrer';a.textContent='open your enquiry here';note.append(a);});}

